import{_ as a,o as _,c as e,a3 as t}from"./chunks/framework.DdpBa4_E.js";const s="/ReadBooks/assets/image-059.B-caG7d8.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/49-派遣雇员、自由打工者不利于结婚和生育.md","filePath":"books/xialiu-shehui/49-派遣雇员、自由打工者不利于结婚和生育.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/49-派遣雇员、自由打工者不利于结婚和生育.md"};function i(r,p,l,n,d,c){return _(),e("div",null,[...p[0]||(p[0]=[t('<h2 id="派遣雇员、自由打工者不利于结婚和生育" tabindex="-1">派遣雇员、自由打工者不利于结婚和生育 <a class="header-anchor" href="#派遣雇员、自由打工者不利于结婚和生育" aria-label="Permalink to &quot;派遣雇员、自由打工者不利于结婚和生育&quot;">​</a></h2><p>如果我们从各种不同职业来就婚姻状况及家庭形态作一考察，则可以发现：女性派遣雇员及自由打工者在结婚和生育方面处于很不利的境地（见表4-20）。</p><p>表4-20　各种不同职业与婚姻状况及家庭形态的关系</p><p><img src="'+s+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>进一步对职业按照年龄段来细分，则从事企业一般辅助性事务工作的女性在23—27岁时有53.0%的人未婚，并且与父母亲生活在一起，还有39.4%的人未婚但独身一人生活。然而到了28—32岁年龄段，所谓的“啃老族”却并不见减少，仍然有43.4%，同时还有23.7%的人结婚，其中有9.8%的人生育了孩子。在33—37岁年龄段的女性中，有44.3%的人已婚，并且有21.6%的人育有孩子。在23—27岁年龄段时有132名女性从事企业辅助性事务工作，至33—37岁年龄段时已减为88人，即减少至原来的三分之二，另三分之一据推测是以结婚或生育为契机而辞去了工作。</p><p>而从事企业综合事务工作的女性，在23—27岁年龄段时未婚且与父母生活在一起的人有54.3%，与从事企业一般辅助性事务的人数相差无几，至28—32岁年龄段时有27.2%的人已婚，其中9.1%的人育有孩子。27.2%已婚，这个比例看上去似乎多于从事一般辅助性事务的女性，但是如前所述，是因为从事一般辅助性事务的女性有不少人结婚后辞去工作所致，而非从事综合事务的女性结婚早的缘故。</p><p>乍一看，容易让人产生一个错觉，似乎从事企业综合事务工作的女性相对来说结婚较晚，但就表中数据来看，并不能得出这样的结论。可以说，从事企业综合事务工作的女性与从事一般辅助性事务工作的女性一样，结婚、生育的进度无甚明显的差异。</p><p>值得注目的倒是，28—32岁年龄段已婚无子、从事企业综合事务工作的女性中，有4.5%的人与父母生活在一起，至33—37岁年龄段时，尽管有41.2%已婚，并且其中17.7%的人已经育有孩子，但是仍然有5.9%的人与父母生活在一起。换句话说，对于从事企业综合事务工作的已婚女性来说，使其能够继续工作下去的一个重要原因，便是女性的母亲帮忙替其照看孩子，在周刊AERA的特辑中也经常会读到类似的报道。</p><p>不过，从事企业综合事务工作的女性在23—27岁年龄段时有46人，至33—37岁年龄段时减为17人。虽然以上数据并非针对同一世代的长期跟踪调查，因而还不能够断言，但至少可以认为存在着这样的可能性，即从事企业综合事务工作的女性，自进入企业起经过约十年的时间，也有约三分之二的人因结婚和生育而辞去了工作。</p><p>再看派遣雇员的情形又如何呢？</p><p>派遣雇员及兼职雇员的人数并没有随着年龄的增大而大幅减少，23—27岁时共有85人，33—37岁时仍有60人。</p><p>派遣雇员在23—27岁年龄段时有47.1%的人未婚且与父母生活在一起，略少于从事企业综合事务或辅助性事务工作的女性，而独身一人生活的有43.5%，略多于从事企业综合事务或辅助性事务工作的女性。出现这种反差的个中原因尚不明了，估计是从地方城镇来到大都市工作的女性，在就职方面处于不利的地位，较难成为企业正式雇员的缘故吧。</p><p>派遣雇员在28—32岁年龄段时仍然未婚并且与父母生活在一起的有45.9%，但是独身一人生活的人数却有所减少，已婚比例为26.0%，然而其中育有孩子的却仅有2.5%，明显低于从事企业综合事务或辅助性事务工作的女性。至33—37岁年龄段时，仍有35.0%的人坚持与父母生活在一起，已婚率虽上升至43.4%，但育有孩子的人数比例仍只有极低的5.0%。</p><p>根据以上的调查结果，不难得出这样一个假设，即派遣雇员这种雇佣形式，对于女性的结婚以及生育是非常不利的。目前日本旨在应对少子化问题的政策更多的是面向企业中包括从事综合事务和一般辅助性事务工作的女性正式雇员，是针对她们的实际困难而拟就的对策，而现今派遣雇员及兼职雇员不断增多，并且她们即使坚持工作，收入却依然长期得不到提升，因而给结婚及生育都带来极大影响的情况下，假如拿不出更好的对策打破这种不合理的现象，则从根本上解决少子化问题恐怕只能是一句空话。</p><p>最后来看看自由打工族的情况。自由打工族在23—27岁年龄段时有73.7%的人与父母生活在一起，28—32岁年龄段时仍有69.2%的与父母一起生活，而已婚率仅有3.8%，育有孩子的人数为零。至33—37岁年龄段时，仍有63.6%的人与父母生活在一起，而已婚者仅有1人，占比例为9.1%，并且还是与父母生活在一起，而育有孩子的人数比例仍然为零。</p><p>当然，女性结婚后多回答职业为专职家庭主妇，而结婚后仍然以自由打工者身份回答调查的，只能是那些婚后与父母生活在一起、“啃老”的自由打工族夫妇，即夫妇双方都为无固定职业的自由打工族，他们因为收入微薄，不足以独立负担一个家庭的庞大支出，只能选择继续生活在父母身边。在本次调查中，有一个案例便是这样的女性。</p>',17)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
